#include "CargoRailRuntime.hpp"
#include <limits>
namespace elysium::travel {bool CargoRailRuntime::addEdge(RailEdge e){if(!e.id||!e.from||!e.to)return false;e.cost=std::max(0.0,e.cost);return edges_.emplace(e.id,e).second;}bool CargoRailRuntime::addCart(Cart c){if(!c.id||c.capacity<0)return false;return carts_.emplace(c.id,c).second;}std::vector<StableId>CargoRailRuntime::route(StableId s,StableId goal)const{struct N{double d;StableId v;bool operator>(const N&o)const{return d>o.d||(d==o.d&&v>o.v);}};std::priority_queue<N,std::vector<N>,std::greater<N>>q;std::unordered_map<StableId,double>d;std::unordered_map<StableId,StableId>p;d[s]=0;q.push({0,s});while(!q.empty()){auto n=q.top();q.pop();if(n.v==goal)break;for(auto&[id,e]:edges_)if(e.enabled&&e.from==n.v){double nd=n.d+e.cost;if(!d.count(e.to)||nd<d[e.to]){d[e.to]=nd;p[e.to]=n.v;q.push({nd,e.to});}}}if(!d.count(goal))return{};std::vector<StableId>out;for(auto v=goal;v!=s;v=p[v])out.push_back(v);out.push_back(s);std::reverse(out.begin(),out.end());return out;}}
